const bytes=p=>fs.readFileSync(new URL('../'+p,import.meta.url));const load=p=>JSON.parse(bytes(p));const sha256=p=>createHash('sha256').update(bytes(p)).digest('hex');const gitBlob=p=>{const b=bytes(p);return createHash('sha1').update(Buffer.from('blob '+b.length+'\0')).update(b).digest('hex');};const zero={x:0,y:0,z:0},forward={x:0,y:0,z:1};
const box=(x,y,z,width=.6)=>({center:{x,y,z},extent:{x:width/2,y:1,z:width/2}});
test('source health multiplier uses Java float32 and current HP',()=>{assert.equal(shriekDamage(20),24);assert.equal(shriekDamage(7),Math.fround(Math.fround(7)*Math.fround(1.2)));assert.equal(shriekDamage(.5),Math.fround(.6));for(const bad of[0,-1,NaN,Infinity])assert.throws(()=>shriekDamage(bad));});
test('ray hit boundaries are inclusive at 0 and 32, excludes rear/beyond',()=>{assert(shriekHit(zero,forward,box(0,0,0)));assert(shriekHit(zero,forward,box(0,0,32)));assert(!shriekHit(zero,forward,box(0,0,-.001)));assert(!shriekHit(zero,forward,box(0,0,32.001)));});
test('halfwidth-aware corridor is Euclidean, not axis-aligned damage cube',()=>{assert(shriekHit(zero,forward,box(1.3,0,10)));assert(!shriekHit(zero,forward,box(1.301,0,10)));assert(!shriekHit(zero,forward,box(1,1,10)));assert(shriekHit(zero,forward,box(2.5,0,10,4)));});
test('ray can look vertically or diagonally, no horizontal-only accidental hits',()=>{assert(shriekHit(zero,{x:0,y:10,z:0},box(0,20,0)));assert(!shriekHit(zero,{x:0,y:10,z:0},box(0,-20,0)));const u=unit({x:1,y:1,z:1});assert(shriekHit(zero,u,box(u.x*31,u.y*31,u.z*31)));});
test('source knockback threshold and additive vector are exact',()=>{assert.deepEqual(shriekImpulse(forward),{x:0,y:.28,z:.63});assert.deepEqual(shriekImpulse({x:0,y:1,z:0}),{x:0,y:.28,z:0});const d=shriekImpulse({x:1,y:0,z:1});assert(Math.abs(d.x-.63/Math.sqrt(2))<1e-12);});
test('exactly16 visual points at2..32 along full normalized direction',()=>{const p=shriekParticles({x:4,y:2,z:1},{x:0,y:0,z:3});assert.equal(p.length,16);assert.deepEqual(p[0],{x:4,y:2,z:3});assert.deepEqual(p.at(-1),{x:4,y:2,z:33});});
test('invalid vectors/negative AABB extents rejected, not guessed',()=>{assert.throws(()=>unit(zero));assert.throws(()=>shriekHit(zero,forward,box(NaN,0,2)));assert.throws(()=>shriekHit(zero,forward,{center:zero,extent:{x:-1,y:1,z:1}}));});
test('instant custom effects never become persisted ticking effects',()=>{for(const id of['kaleidoscope_tavern:shriek_attack','kaleidoscope_tavern:upside_down']){assert.throws(()=>addStatus(readStatus(),id,100,0));assert.throws(()=>readStatus(JSON.stringify({schema:1,entries:[{id,ticks:100,amplifier:0}]})));}});
test('upside-down Java-style inflated AABB uses strict overlap and target extents',()=>{const source={center:{x:0,y:1,z:0},extent:{x:.3,y:1,z:.3}};assert(inflatedAabbIntersects(source,{center:{x:16.5,y:17,z:16.5},extent:{x:.3,y:1,z:.3}},16));assert(!inflatedAabbIntersects(source,{center:{x:16.6,y:1,z:0},extent:{x:.3,y:1,z:.3}},16));assert(!inflatedAabbIntersects(source,{center:{x:16.61,y:17,z:16.61},extent:{x:.3,y:1,z:.3}},16));assert.throws(()=>inflatedAabbIntersects(source,{center:{x:0,y:0,z:0},extent:{x:-1,y:1,z:1}},16));});
for(const color of COLORS)test('source stool color contract: '+color,()=>{const f={kind:'stool',color};assert.deepEqual(furnitureItem(itemId(f)),f);assert.deepEqual(furnitureBlock(blockId(f)),f);assert.equal(seatColor(seatId(color)),color);const e=load('runtime/BP/entities/seat_'+color+'.json')['minecraft:entity'];assert.deepEqual(e.components['minecraft:rideable'].seats,[{position:[0,.8125,0]}]);assert.equal(e.components['minecraft:rideable'].seat_count,1);assert(!e.components['minecraft:rideable'].pull_in_entities);const r=load('runtime/BP/recipes/'+color+'_bar_stool.json')['minecraft:recipe_shaped'];assert.deepEqual(r.pattern,['W','C','L']);assert.equal(r.key.W.item,'minecraft:'+color+'_wool');assert.equal(r.result.count,1);});
for(const color of LIGHT_COLORS)test('distinct source light and level15: '+color,()=>{const f={kind:'light',color};assert.deepEqual(furnitureItem(itemId(f)),f);const b=load('runtime/BP/blocks/light_'+color+'.json')['minecraft:block'];assert.equal(b.components['minecraft:light_emission'],15);assert.equal(b.components['minecraft:collision_box'],false);assert.equal(b.permutations.length,4);const r=load('runtime/BP/recipes/string_lights_'+color+'.json')['minecraft:recipe_shaped'];assert.equal(r.result.count,8);assert.equal(r.pattern.length,color==='colorless'?2:3);});
test('vertical double helper is symmetric and rejects unknown half',()=>{assert.deepEqual(verticalDoublePartner(DOUBLE_HALF.UPPER),{half:DOUBLE_HALF.LOWER,offset:{x:0,y:-1,z:0}});assert.deepEqual(verticalDoublePartner(DOUBLE_HALF.LOWER),{half:DOUBLE_HALF.UPPER,offset:{x:0,y:1,z:0}});assert.throws(()=>verticalDoublePartner(2));});
for(const style of PENDANT_LAMP_STYLES)test('source two-block Pendant Lamp contract: '+style,()=>{const f={kind:'pendant_lamp',style};assert.deepEqual(furnitureItem(itemId(f)),f);assert.deepEqual(furnitureBlock(blockId(f)),f);assert.equal(itemId(f),NS+':'+style+'_pendant_lamp');const b=load('runtime/BP/blocks/'+style+'_pendant_lamp.json')['minecraft:block'];assert.deepEqual(b.description.states[HALF],[0,1]);assert.equal(b.components['minecraft:collision_box'],false);assert.equal(b.permutations.length,8);assert.equal(b.permutations.filter(x=>x.components['minecraft:light_emission']===13).length,4);assert.equal(b.permutations.filter(x=>x.components['minecraft:light_emission']===0).length,4);const r=load('runtime/BP/recipes/'+style+'_pendant_lamp.json')['minecraft:recipe_shaped'];assert.deepEqual(r.pattern,['C','C','B']);assert.equal(r.result.count,style==='bell'?8:4);});
test('Painting Java placement state preserves wall/floor/ceiling facing rules',()=>{assert.deepEqual(paintingPlacementState('North',0),{attach:PAINTING_ATTACH.WALL,facing:0});assert.deepEqual(paintingPlacementState('East',180),{attach:PAINTING_ATTACH.WALL,facing:1});assert.deepEqual(paintingPlacementState('Up',0),{attach:PAINTING_ATTACH.FLOOR,facing:2});assert.deepEqual(paintingPlacementState('Up',90),{attach:PAINTING_ATTACH.FLOOR,facing:3});assert.deepEqual(paintingPlacementState('Down',0),{attach:PAINTING_ATTACH.CEILING,facing:0});assert.deepEqual(paintingPlacementState('Down',90),{attach:PAINTING_ATTACH.CEILING,facing:1});assert.throws(()=>paintingPlacementState('Sideways',0));});
for(const style of PAINTING_STYLES)test('source attachable Painting contract: '+style,()=>{const f={kind:'painting',style};assert.deepEqual(furnitureItem(itemId(f)),f);assert.deepEqual(furnitureBlock(blockId(f)),f);assert.equal(itemId(f),NS+':'+style+'_painting');const b=load('runtime/BP/blocks/'+style+'_painting.json')['minecraft:block'];assert.deepEqual(b.description.states[FACING],[0,1,2,3]);assert.deepEqual(b.description.states[ATTACH_FACE],[0,1,2]);assert.equal(b.components['minecraft:geometry'].identifier,'geometry.kt_runtime.painting_wall');assert.equal(b.permutations.length,12);assert(b.permutations.every(x=>x.components['minecraft:collision_box']&&x.components['minecraft:selection_box']));const raw=load('runtime/BP/recipes/'+style+'_painting.json');if(style==='mondrian')assert(raw['minecraft:recipe_shaped']);else assert(raw['minecraft:recipe_shapeless']);});
test('all14 Painting block placements match Java facing rotations and collision boxes',()=>{const wall=[{origin:[-7,1,7],size:[14,14,1]},{origin:[-8,1,-7],size:[1,14,14]},{origin:[-7,1,-8],size:[14,14,1]},{origin:[7,1,-7],size:[1,14,14]}],floor={origin:[-7,0,-7],size:[14,1,14]},ceiling={origin:[-7,15,-7],size:[14,1,14]},rotations={0:{0:[0,0,0],1:[0,270,0],2:[0,180,0],3:[0,90,0]},1:{0:[0,0,0],1:[0,90,0],2:[0,180,0],3:[0,270,0]},2:{0:[0,0,0],1:[0,90,0],2:[0,180,0],3:[0,270,0]}};for(const style of PAINTING_STYLES){const b=load('runtime/BP/blocks/'+style+'_painting.json')['minecraft:block'];for(const attach of[0,1,2])for(let facing=0;facing<4;facing++){const p=b.permutations.find(x=>x.condition.includes(`'kaleidoscope_tavern:attach_face') == ${attach}`)&&x.condition.includes(`'kaleidoscope_tavern:facing') == ${facing}`));assert(p,`${style} attach=${attach} facing=${facing}`);const shape=attach===0?wall[facing]:attach===1?floor:ceiling,box=p.components['minecraft:collision_box'];assert.deepEqual([box.origin,box.size],[shape.origin,shape.size],`${style} box attach=${attach} facing=${facing}`);assert.deepEqual(p.components['minecraft:selection_box'],box,`${style} selection attach=${attach} facing=${facing}`);assert.deepEqual(p.components['minecraft:transformation'].rotation,rotations[attach][facing],`${style} rotation attach=${attach} facing=${facing}`);}}});
test('Painting family stays exactly the14 Java 1.2.0 variants',()=>{assert.equal(PAINTING_STYLES.length,14);assert.equal(new Set(PAINTING_STYLES).size,14);assert.equal(furnitureItem(NS+':invented_painting'),undefined);});
test('Painting item transforms preserve all Java display contexts for all14 block items',()=>{const geometry=load('runtime/RP/models/entity/painting_wall.geo.json')['minecraft:geometry'][0];assert.equal(geometry.description.identifier,'geometry.kt_runtime.painting_wall');assert.deepEqual(geometry.item_display_transforms,{thirdperson_righthand:{rotation:[75,45,0],translation:[0,2.5,0],scale:[.375,.375,.375]},thirdperson_lefthand:{rotation:[75,45,0],translation:[0,2.5,0],scale:[.375,.375,.375]},firstperson_righthand:{rotation:[0,-180,0],translation:[5,2.25,0],scale:[.4,.4,.4]},firstperson_lefthand:{rotation:[0,-180,0],translation:[5,2.25,0],scale:[.4,.4,.4]},ground:{translation:[0,3,0],scale:[.25,.25,.25]},gui:{rotation:[18,147,0],translation:[-3.25,-1.5,0],scale:[.85,.85,.85]},head:{translation:[0,14.25,.75]},fixed:{translation:[0,0,-6.75]}});for(const style of PAINTING_STYLES){const b=load('runtime/BP/blocks/'+style+'_painting.json')['minecraft:block'];assert.equal(b.components['minecraft:item_visual'].geometry.identifier,geometry.description.identifier,style);assert.equal(b.permutations.length,12,style);}});
test('all source color families remain complete without inventing twentieth colors',()=>{assert.equal(COLORS.length,16);assert.equal(LIGHT_COLORS.length,17);assert.equal(furnitureItem('kaleidoscope_tavern:uv_bar_stool'),undefined);assert.equal(dyeColor('minecraft:red_dye'),'red');assert.equal(dyeColor('minecraft:rose_red'),undefined);assert.throws(()=>seatId('ultraviolet'));});
test('anchor roundtrip separates dimensions and supports negative coordinates',()=>{for(const d of['minecraft:overworld','minecraft:nether'])assert.deepEqual(anchorPosition(anchorKey(d,{x:-3,y:64,z:0})),{dimension:d,position:{x:-3,y:64,z:0}});assert.throws(()=>anchorPosition('bad'));assert.throws(()=>anchorKey('minecraft:overworld',{x:1.2,y:0,z:0}));});
test('all4 cardinal directions and seat angles wrap predictably',()=>{assert.deepEqual([0,90,180,270].map(facingForYaw),[0,1,2,3]);assert.deepEqual([0,1,2,3].map(facingYaw),[180,-90,0,90]);assert.equal(relativeSeatYaw(-170,170),20);assert.equal(facingForFace('North',0),0);assert.deepEqual(faceOffset('Up'),{x:0,y:1,z:0});assert.throws(()=>faceOffset('invalid'));});
test('turn animation affects cushion only, not base_root',()=>{const a=load('runtime/RP/animations/runtime_furniture.animation.json').animations['animation.kt_runtime.stool.turn'];assert.deepEqual(Object.keys(a.bones),['bone']);assert.equal(a.bones.bone.rotation[1],'v.kt_seat_angle');const cl=load('runtime/RP/entity/runtime_seat_blue.entity.json')['minecraft:client_entity'].description;assert(cl.scripts.pre_animation[0].includes('math.lerprotate'));assert(cl.scripts.pre_animation[0].includes('q.delta_time'));});
