test('Vision source radius is 6/12/18 and caps at amplifier2',()=>{assert.equal(visionRadius(0),6);assert.equal(visionRadius(1),12);assert.equal(visionRadius(2),18);assert.equal(visionRadius(255),18);assert.throws(()=>visionRadius(-1));});
test('Vision 50-tick countdown pulse detects crossed Java modulo boundaries',()=>{assert(countdownPulseCrossed(36000,35997,50));assert(!countdownPulseCrossed(35997,35992,50));assert(countdownPulseCrossed(35952,35947,50));assert(countdownPulseCrossed(50,45,50));assert(!countdownPulseCrossed(45,40,50));assert.throws(()=>countdownPulseCrossed(40,45,50));});
test('Tomb Raider maps exact Java disarmable families to Bedrock IDs',()=>{assert.equal(TOMB_RAIDER_TYPES.length,15);for(const id of['minecraft:skeleton','minecraft:stray','minecraft:wither_skeleton','minecraft:bogged','minecraft:skeleton_horse','minecraft:zombie','minecraft:zombie_villager','minecraft:drowned','minecraft:husk','minecraft:piglin','minecraft:piglin_brute','minecraft:zombie_pigman','minecraft:vindicator','minecraft:pillager','minecraft:witch'])assert(tombRaiderTarget(id),id);for(const id of['minecraft:creeper','minecraft:evocation_illager','minecraft:player','minecraft:zombified_piglin'])assert(!tombRaiderTarget(id),id);});
test('Tomb Raider 30 percent roll preserves Java float32 boundary',()=>{assert.equal(TOMB_RAIDER_CHANCE,Math.fround(.3));assert(tombRaiderProc(.299999));assert.equal(tombRaiderProc(.3),false);assert.equal(tombRaiderProc(.300001),false);for(const bad of[-.1,1,NaN,Infinity])assert.throws(()=>tombRaiderProc(bad));});
test('Ardent Heat expands exact Java base-stone tags without fuzzy matching',()=>{assert.deepEqual(ARDENT_HEAT_BLOCKS,['minecraft:stone','minecraft:granite','minecraft:diorite','minecraft:andesite','minecraft:tuff','minecraft:deepslate','minecraft:netherrack','minecraft:basalt','minecraft:blackstone','minecraft:end_stone']);for(const id of ARDENT_HEAT_BLOCKS)assert(ardentHeatBreakable(id));for(const id of['minecraft:cobblestone','minecraft:stone_bricks','minecraft:end_stone_bricks','kaleidoscope_tavern:stool_blue'])assert(!ardentHeatBreakable(id));assert.equal(ardentHeatDrop('minecraft:stone'),'minecraft:cobblestone');assert.equal(ardentHeatDrop('minecraft:deepslate'),'minecraft:cobbled_deepslate');assert.equal(ardentHeatDrop('minecraft:basalt'),'minecraft:basalt');assert.equal(ardentHeatDrop('minecraft:cobblestone'),undefined);});
test('Ardent Heat front plane is source 3x3 at feet through +2 for four cardinal yaws',()=>{const base={x:10,y:64,z:20};const want=[[{x:9,y:64,z:21},{x:10,y:64,z:21},{x:11,y:64,z:21}],[{x:9,y:64,z:19},{x:9,y:64,z:20},{x:9,y:64,z:21}],[{x:9,y:64,z:19},{x:10,y:64,z:19},{x:11,y:64,z:19}],[{x:11,y:64,z:19},{x:11,y:64,z:20},{x:11,y:64,z:21}]];for(const [i,yaw]of [0,90,180,-90].entries()){const p=ardentFrontBlocks(base,yaw);assert.equal(p.length,9);assert.deepEqual(p.filter(x=>x.y===64),want[i]);assert.deepEqual([...new Set(p.map(x=>x.y))],[64,65,66]);}assert.throws(()=>ardentFrontBlocks({x:1.2,y:2,z:3},0));});
test('official c4ec188 magenta string-light culling fix keeps all12 rotated thin planes double-sided',()=>{const src=load('data/upstream/post-1.2/c4ec1880/string_lights_magenta.json');assert.equal(src.elements.length,19);const sourceThin=src.elements.filter(e=>e.rotation&&Object.keys(e.faces).includes('up')&&Object.keys(e.faces).includes('down')&&e.from.some((v,i)=>v===e.to[i]));assert.equal(sourceThin.length,12);for(const path of['art/RP/models/entity/string_lights_magenta.geo.json','runtime/RP/models/entity/string_lights_magenta.geo.json']){const g=load(path)['minecraft:geometry'][0],thin=g.bones[0].cubes.filter(c=>c.rotation&&c.size.includes(0));assert.equal(thin.length,12,path);assert(thin.every(c=>c.uv?.up&&c.uv?.down),path);}});
test('official b30f34a gold grape bucket texture is byte-exact in locked source and both runtime copies',()=>{const expected='ae8dd1d9802fa02568c3eb457b9e1bacf25d92047faf67bf3dd78bb7ae5691d0';for(const path of['data/upstream/post-1.2/b30f34a/gold_grape_bucket.png','runtime/RP/textures/kaleidoscope_tavern/item/gold_grape_bucket.png','runtime/RP/textures/kaleidoscope_tavern_jar/item/gold_grape_bucket.png'])assert.equal(sha256(path),expected,path);});
test('High Heels maps raw movement to yaw-relative cardinal travel',()=>{assert.deepEqual(highHeelsDirection(0,{x:0,y:1}),{x:0,z:1});assert.deepEqual(highHeelsDirection(0,{x:1,y:0}),{x:1,z:0});assert.deepEqual(highHeelsDirection(90,{x:0,y:1}),{x:-1,z:0});assert.deepEqual(highHeelsDirection(-90,{x:0,y:1}),{x:1,z:0});assert.deepEqual(highHeelsDirection(180,{x:0,y:-1}),{x:0,z:1});assert.equal(highHeelsDirection(0,{x:0,y:HIGH_HEELS_INPUT_MIN-.01}),undefined);});
test('High Heels only arms when movement input is strong but horizontal motion is blocked',()=>{assert(highHeelsBlocked({x:0,y:1},{x:0,y:0,z:0}));assert(!highHeelsBlocked({x:0,y:HIGH_HEELS_INPUT_MIN-.01},{x:0,y:0,z:0}));assert(!highHeelsBlocked({x:0,y:1},{x:HIGH_HEELS_SPEED_MAX+.01,y:0,z:0}));assert(!highHeelsBlocked({x:0,y:1},{x:0,y:.09,z:0}));assert.throws(()=>highHeelsBlocked({x:NaN,y:1},{x:0,y:0,z:0}));});
test('High Heels waits for the collision edge and raises one block with small forward carry',()=>{assert(highHeelsNearBoundary({x:.5,y:65,z:2.7},{x:0,z:1}));assert(!highHeelsNearBoundary({x:.5,y:65,z:2.4},{x:0,z:1}));assert(highHeelsNearBoundary({x:-.3,y:65,z:2.5},{x:1,z:0}));const t=highHeelsTarget({x:.5,y:65,z:2.7},{x:0,z:1});assert.equal(t.x,.5);assert.equal(t.y,66);assert(Math.abs(t.z-2.9)<1e-12);assert.throws(()=>highHeelsNearBoundary({x:0,y:0,z:0},{x:1,z:1}));});
for(const color of COLORS)test('source sofa contract: '+color,()=>{const f={kind:'sofa',color};assert.deepEqual(furnitureItem(itemId(f)),f);assert.deepEqual(furnitureBlock(blockId(f)),f);assert.equal(itemId(f),NS+':'+color+'_sofa');assert.equal(blockId(f),itemId(f));assert.equal(seatEntityId(f),SOFA_SEAT_ID);const b=load('runtime/BP/blocks/'+color+'_sofa.json')['minecraft:block'];assert.deepEqual(b.description.states[CONNECTION],[0,1,2,3,4,5]);assert.equal(b.permutations.filter(x=>x.condition.includes(CONNECTION)).length,6);assert.equal(b.components['minecraft:item_visual'].geometry.identifier,'geometry.kt_assets_a17.item_display_'+color+'_sofa');const r=load('runtime/BP/recipes/'+color+'_sofa.json')['minecraft:recipe_shaped'];assert.deepEqual(r.pattern,['W W','WWW','L L']);assert.equal(r.key.W.item,'minecraft:'+color+'_wool');assert.equal(r.key.L.item,'minecraft:iron_ingot');assert.equal(r.result.item,NS+':'+color+'_sofa');});
