test('c70eec model-only sync plan is source-locked and applied to all four cocktails',()=>{const root='data/upstream/post-1.2/c70eec1/model-only-1/',plan=load(root+'sync-plan.json');assert.equal(plan.mode,'shade_cutout');assert.deepEqual(plan.models.map(x=>x.id),['brass_heart','emerald','godfather','nether_special']);for(const m of plan.models){assert.equal(gitBlob(root+m.baseline),m.baseline_blob,m.id+' baseline');assert.equal(gitBlob(root+m.updated),m.updated_blob,m.id+' updated');const old=load(root+m.baseline),next=load(root+m.updated);assert.equal(old.render_type,'translucent');assert.equal(next.render_type,'cutout');const block=load(m.block)['minecraft:block'].components;for(const group of[block['minecraft:material_instances'],block['minecraft:item_visual'].material_instances])for(const v of Object.values(group))assert.equal(v.render_method,'alpha_test_single_sided',m.id);const cubes=load(m.geo)['minecraft:geometry'][0].bones[0].cubes;for(const i of m.unshaded_cubes)for(const face of Object.values(cubes[i].uv))assert.equal(face.material_instance,'unshaded',m.id+' cube '+i);}});
