test('Bar Cabinet source irregular tag is exactly brandy/carignan and all BottleBlock shapes remain admissible',()=>{assert.deepEqual(BAR_CABINET_IRREGULAR,['brandy','carignan']);for(const id of[NS+':empty_bottle',NS+':wine_q5',NS+':vodka_q6',NS+':brandy_q2',NS+':carignan_q4'])assert(barCabinetItem(id),id);assert(barCabinetIrregular(NS+':brandy_q1'));assert(barCabinetIrregular(NS+':carignan_q6'));for(const id of[NS+':white_lady',NS+':molotov',NS+':empty_glassware'])assert.equal(barCabinetItem(id),undefined,id);});
test('Bar Cabinet two-slot Java redirection and irregular single mode are exact',()=>{let s=emptyBarCabinet();let tx=barCabinetPut(s,true,NS+':wine_q5');assert(tx.changed&&tx.side==='left');s=tx.state;tx=barCabinetPut(s,true,NS+':vodka_q6');assert(tx.changed&&tx.side==='right');s=tx.state;assert.deepEqual([s.left,s.right,s.single],[NS+':wine_q5',NS+':vodka_q6',false]);assert.equal(barCabinetPut(s,false,NS+':brandy_q2').changed,false);let one=barCabinetTake(s,true).state;one=barCabinetTake(one,false).state;assert.deepEqual(one,barCabinetTake(one,true).state);let ir=barCabinetPut(emptyBarCabinet(),false,NS+':brandy_q2').state;assert.deepEqual([ir.left,ir.right,ir.single],[NS+':brandy_q2',null,true]);assert.equal(barCabinetPut(ir,true,NS+':wine_q1').changed,false);const take=barCabinetTake(ir,false);assert.equal(take.side,'left');assert.equal(take.item,NS+':brandy_q2');assert.equal(take.state.single,false);});
test('Bar Cabinet clicked left side follows Java facing rule and line connection preserves same-type only',()=>{assert.equal(barCabinetClickedLeft(0,{x:.8,z:.5}),true);assert.equal(barCabinetClickedLeft(2,{x:.2,z:.5}),true);assert.equal(barCabinetClickedLeft(1,{x:.5,z:.2}),true);assert.equal(barCabinetClickedLeft(3,{x:.5,z:.8}),true);const t=CABINET_TYPES[0],g=CABINET_TYPES[1];assert.equal(barCabinetPosition(t,0,{}),CABINET_POSITION.SINGLE);assert.equal(barCabinetPosition(t,0,{left:{typeId:t,facing:0}}),CABINET_POSITION.RIGHT);assert.equal(barCabinetPosition(t,0,{right:{typeId:t,facing:0}}),CABINET_POSITION.LEFT);assert.equal(barCabinetPosition(t,0,{left:{typeId:t,facing:0},right:{typeId:t,facing:0}}),CABINET_POSITION.MIDDLE);assert.equal(barCabinetPosition(t,0,{left:{typeId:g,facing:0}}),CABINET_POSITION.SINGLE);});
test('Bar Cabinet state keys/visual pose preserve source center single and split regular bottles',()=>{const k=barCabinetKey('minecraft:overworld',{x:-2,y:64,z:5},NS+':bar_cabinet');assert.deepEqual(parseBarCabinetAnchor(barCabinetAnchor(k,'right')),{dimension:'minecraft:overworld',typeId:NS+':bar_cabinet',position:{x:-2,y:64,z:5},side:'right'});assert.deepEqual(barCabinetVisualPose('left',true,0),{offset:{x:.5,y:.0625,z:.5},rotation:{x:0,y:0}});assert.deepEqual(barCabinetVisualPose('left',false,0),{offset:{x:.75,y:.0625,z:.5},rotation:{x:0,y:0}});assert.deepEqual(barCabinetVisualPose('right',false,0),{offset:{x:.25,y:.0625,z:.5},rotation:{x:0,y:0}});});
test('Bar Cabinet and Glass Bar Cabinet use source four connection geometries and full-block collision',()=>{for(const short of['bar_cabinet','glass_bar_cabinet']){const b=load('runtime/BP/blocks/'+short+'.json')['minecraft:block'];assert.deepEqual(b.description.states[POSITION],[0,1,2,3]);assert.deepEqual(b.description.states[FACING],[0,1,2,3]);assert.deepEqual(b.components['minecraft:collision_box'],{origin:[-8,0,-8],size:[16,16,16]});assert.equal(b.permutations.filter(x=>x.condition.includes('position')).length,4);assert.equal(b.permutations.filter(x=>x.condition.includes('facing')).length,4);}});
test('Glass Bar Cabinet expands Java c:glass_panes to clear plus sixteen stained pane recipes',()=>{const names=fs.readdirSync(new URL('../runtime/BP/recipes/',import.meta.url)).filter(x=>x.startsWith('glass_bar_cabinet')&&x.endsWith('.json'));assert.equal(names.length,17);const panes=new Set(names.map(n=>load('runtime/BP/recipes/'+n)['minecraft:recipe_shaped'].key.P.item));assert.equal(panes.size,17);assert(panes.has('minecraft:glass_pane'));assert(panes.has('minecraft:black_stained_glass_pane'));const r=load('runtime/BP/recipes/bar_cabinet.json')['minecraft:recipe_shaped'];assert.deepEqual(r.pattern,['GGG','G G','GGG']);assert.equal(r.key.G.item,NS+':grapevine');});
test('Cellar Cabinet source blocklist matches Holder and accepts only empty bottle plus14 regular quality bases',()=>{for(const id of[NS+':empty_bottle',NS+':wine_q5',NS+':champagne_q2'])assert(cellarCabinetItem(id),id);for(const id of[NS+':brandy_q1',NS+':carignan_q6',NS+':vodka_q4',NS+':rum_q2',NS+':white_lady',NS+':molotov'])assert.equal(cellarCabinetItem(id),undefined,id);});
test('Cellar Cabinet front-only Java3x3 hit mapping is exact for all facings',()=>{assert.equal(cellarCabinetSlot(0,'North',{x:.9,y:.9,z:0}),0);assert.equal(cellarCabinetSlot(0,'North',{x:.5,y:.5,z:0}),4);assert.equal(cellarCabinetSlot(0,'North',{x:.1,y:.1,z:0}),8);assert.equal(cellarCabinetSlot(0,'South',{x:.5,y:.5,z:1}),-1);assert.equal(cellarCabinetSlot(1,'East',{x:1,y:.9,z:.9}),0);assert.equal(cellarCabinetSlot(2,'South',{x:.1,y:.1,z:1}),6);assert.equal(cellarCabinetSlot(3,'West',{x:0,y:.5,z:.1}),3);});
test('Cellar Cabinet state preserves nine independent exact-quality IDs',()=>{let s=emptyCellarCabinet();const ids=[NS+':wine_q1',NS+':wine_q2',NS+':champagne_q3',NS+':sherry_q4',NS+':whiskey_q5',NS+':vinegar_q6',NS+':empty_bottle',NS+':plum_wine_q2',NS+':red_queen_q3'];for(let i=0;i<9;i++)s=cellarCabinetPut(s,i,ids[i]);assert.deepEqual(s.slots,ids);const tx=cellarCabinetTake(s,4);assert.equal(tx.item,NS+':whiskey_q5');assert.equal(tx.state.slots[4],null);assert.equal(validateCellarCabinet(tx.state),tx.state);const k=cellarCabinetKey('minecraft:overworld',{x:-2,y:64,z:5});assert.deepEqual(parseCellarCabinetAnchor(cellarCabinetAnchor(k,8)),{dimension:'minecraft:overworld',position:{x:-2,y:64,z:5},slot:8});});
test('Cellar Cabinet same-facing line connection uses source single-left-middle-right states',()=>{const n={typeId:NS+':cellar_cabinet',facing:0};assert.equal(cellarCabinetPosition(0,{}),CABINET_POSITION.SINGLE);assert.equal(cellarCabinetPosition(0,{left:n}),CABINET_POSITION.RIGHT);assert.equal(cellarCabinetPosition(0,{right:n}),CABINET_POSITION.LEFT);assert.equal(cellarCabinetPosition(0,{left:n,right:n}),CABINET_POSITION.MIDDLE);assert.equal(cellarCabinetPosition(0,{left:{typeId:NS+':bar_cabinet',facing:0}}),CABINET_POSITION.SINGLE);});
test('Cellar Cabinet source renderer positions form3x3 shelf with scale1 and -90 X rotation',()=>{const a=cellarCabinetVisualPose(0,0);assert(Math.abs(a.offset.x-.825)<1e-12);assert(Math.abs(a.offset.y-.78)<1e-12);assert.equal(a.offset.z,.875);assert.deepEqual(a.rotation,{x:-90,y:0});const m=cellarCabinetVisualPose(4,0);assert(Math.abs(m.offset.x-.5)<1e-12);assert(Math.abs(m.offset.y-.49)<1e-12);assert.equal(m.offset.z,.875);assert.deepEqual(m.rotation,{x:-90,y:0});const p=cellarCabinetVisualPose(8,0);assert(Math.abs(p.offset.x-.175)<1e-12);assert(Math.abs(p.offset.y-.2)<1e-12);assert.deepEqual(cellarCabinetVisualPose(4,1).rotation,{x:-90,y:90});const c=load('runtime/RP/entity/runtime_cellar_cabinet_bottle_visual.entity.json')['minecraft:client_entity'].description;assert.equal(c.scripts.scale,'1.0');assert.equal(Object.keys(c.geometry).length,15);});
test('Cellar Cabinet uses source four geometries, full block collision and20 trapdoor-expanded recipes',()=>{const b=load('runtime/BP/blocks/cellar_cabinet.json')['minecraft:block'];assert.deepEqual(b.description.states[POSITION],[0,1,2,3]);assert.deepEqual(b.description.states[FACING],[0,1,2,3]);assert.deepEqual(b.components['minecraft:collision_box'],{origin:[-8,0,-8],size:[16,16,16]});assert.equal(b.permutations.filter(x=>x.condition.includes('position')).length,4);const names=fs.readdirSync(new URL('../runtime/BP/recipes/',import.meta.url)).filter(x=>x.startsWith('cellar_cabinet')&&x.endsWith('.json'));assert.equal(names.length,20);const traps=new Set(names.map(n=>load('runtime/BP/recipes/'+n)['minecraft:recipe_shaped'].key.T.item));assert.equal(traps.size,20);assert(traps.has('minecraft:trapdoor'));assert(traps.has('minecraft:waxed_oxidized_copper_trapdoor'));});

test('Cookery guide payload is one organized Tavern family chapter',()=>{
 assert.equal(COOKERY_GUIDE_PAYLOAD.api,1);assert.equal(COOKERY_GUIDE_PAYLOAD.id,'kaleidoscope_tavern:tavern');
 const categories=COOKERY_GUIDE_PAYLOAD.categories;
 assert.deepEqual(categories.filter(x=>!x.parent).map(x=>x.id),['equipment','barrel','cocktail','storage','cultivation','decor']);
 for(const id of ['gear','mix_tools','press','barrel_drinks','cocktail_recipes','store','serve','fruit','press_recipes','furniture','lighting','incense','art','ladder','boards'])assert(categories.some(x=>x.id===id),`missing category ${id}`);
 assert(COOKERY_GUIDE_PAYLOAD.entries.length>=117);
 for(const id of ['kaleidoscope_tavern:base_sandwich_board','kaleidoscope_tavern:chalkboard','kaleidoscope_tavern:stepladder','kaleidoscope_tavern:pine_incense'])assert(COOKERY_GUIDE_PAYLOAD.entries.some(x=>x.id===id),`missing detailed entry ${id}`);
 assert(COOKERY_GUIDE_PAYLOAD.entries.every(x=>COOKERY_GUIDE_PAYLOAD.categories.some(c=>c.id===x.category)));
 for(const entry of COOKERY_GUIDE_PAYLOAD.entries){assert(Array.isArray(entry.mechanics),`mechanics array ${entry.id}`);for(const locale of ['zh_TW','zh_CN','en_US']){assert(Array.isArray(entry.mechanicsByLocale?.[locale])&&entry.mechanicsByLocale[locale].length,`mechanicsByLocale ${locale} ${entry.id}`);assert(typeof COOKERY_GUIDE_PAYLOAD.names[locale]?.[entry.id]==='string'&&COOKERY_GUIDE_PAYLOAD.names[locale][entry.id],`localized label ${locale} ${entry.id}`);}}
 assert.equal(new Set(COOKERY_GUIDE_PAYLOAD.entries.map(x=>x.id)).size,COOKERY_GUIDE_PAYLOAD.entries.length);
 assert.equal(COOKERY_GUIDE_PAYLOAD.text.zh_TW.title,'森羅物語：酒館');
 assert.equal(COOKERY_GUIDE_PAYLOAD.names.zh_TW['kaleidoscope_tavern:guide_bottle_display'],'擺放酒瓶');
});
test('Tavern extension pages and auto recipe pages are projected into the Cookery family guide',()=>{
 const registry={
  list:()=>[{source:'world_liquor',version:'1.0.0',recipes:1,pages:1}],
  allPages:()=>[{id:'world_liquor:about',source:'world_liquor',title:{zh_TW:'異世界酒館',en_US:'World Liquor'},body:{zh_TW:'附屬說明',en_US:'Addon notes'},recipeIds:['world_liquor:apple_wine']}],
  allRecipes:()=>[{id:'world_liquor:apple_wine',source:'world_liquor',kind:'barrel',title:{zh_TW:'蘋果酒',en_US:'Apple Wine'},fluid:'minecraft:water',ingredients:[['minecraft:apple']],carrier:NS+':empty_bottle',output:{item:NS+':wine_q3'}}]
 };
 const payload=buildCookeryGuidePayload(registry),ids=payload.entries.map(x=>x.id);
 assert(payload.categories.some(x=>x.id==='extensions'));assert(ids.includes('world_liquor:about'));assert(ids.includes('world_liquor:apple_wine'));
 assert.equal(payload.names.zh_TW['world_liquor:about'],'異世界酒館');assert.equal(payload.names.en_US['world_liquor:apple_wine'],'Apple Wine');
 assert(payload.entries.find(x=>x.id==='world_liquor:about').mechanics.includes('Addon notes'));
});
test('Cookery guide publisher uses bounded ASCII begin/chunk/end packets and roundtrips payload',()=>{
 const packets=encodeCookeryGuideMessages(COOKERY_GUIDE_PAYLOAD);
 assert.equal(packets[0].id,COOKERY_GUIDE_EVENTS.begin);assert.equal(packets.at(-1).id,COOKERY_GUIDE_EVENTS.end);
 assert(packets.slice(1,-1).every(x=>x.id===COOKERY_GUIDE_EVENTS.chunk));
 assert(packets.every(x=>x.message.length<=2048&&/^[\x00-\x7f]*$/.test(x.message)));
 const begin=JSON.parse(packets[0].message);assert.equal(begin.source,COOKERY_GUIDE_SOURCE);assert.equal(begin.revision,COOKERY_GUIDE_REVISION);
 const raw=packets.slice(1,-1).map(x=>x.message.split('\n').slice(4).join('\n')).join('');
 assert.deepEqual(JSON.parse(raw),COOKERY_GUIDE_PAYLOAD);
});
